package com.bank.persist.storage;

// Describes a storage strategy — exactly what persist(StorageLevel) selects.
public class StorageLevel {
    public final boolean useMemory;
    public final boolean useDisk;
    public final boolean serialized;
    public final boolean offHeap;
    public final int replication;

    public StorageLevel(boolean useMemory, boolean useDisk, boolean serialized,
                        boolean offHeap, int replication) {
        this.useMemory = useMemory;
        this.useDisk = useDisk;
        this.serialized = serialized;
        this.offHeap = offHeap;
        this.replication = replication;
    }

    // The default used by cache() for DataFrames/Datasets.
    public static StorageLevel memoryAndDisk() {
        return new StorageLevel(true, true, false, false, 1);
    }
    // The default used by cache() for RDDs.
    public static StorageLevel memoryOnly() {
        return new StorageLevel(true, false, false, false, 1);
    }
    // Explicit: pack big data tightly and spill to disk.
    public static StorageLevel memoryAndDiskSer() {
        return new StorageLevel(true, true, true, false, 1);
    }
    // Explicit: replicate for fault tolerance.
    public static StorageLevel memoryAndDisk2() {
        return new StorageLevel(true, true, false, false, 2);
    }

    @Override public String toString() {
        return "StorageLevel{mem=" + useMemory + ", disk=" + useDisk
                + ", ser=" + serialized + ", offHeap=" + offHeap + ", repl=" + replication + "}";
    }
}
