package com.bank.persist.storage;

import com.bank.persist.model.Partition;
import java.util.List;
import java.util.logging.Logger;

// Applies a StorageLevel to partitions, reporting memory used and spill.
public class Store {
    private static final Logger log = Logger.getLogger(Store.class.getName());
    private final long memoryCapacityBytes;

    public Store(long memoryCapacityBytes) {
        this.memoryCapacityBytes = memoryCapacityBytes;
    }

    // cache(): use the DEFAULT level (memory-and-disk for DataFrames).
    public void cache(List<Partition> parts) {
        log.info("cache() → default storage level (DataFrame: MEMORY_AND_DISK)");
        store(parts, StorageLevel.memoryAndDisk());
    }

    // persist(StorageLevel): explicit level chosen by the caller.
    public void persist(List<Partition> parts, StorageLevel level) {
        log.info(() -> "persist(" + level + ") → explicit storage strategy");
        store(parts, level);
    }

    private void store(List<Partition> parts, StorageLevel level) {
        long used = 0, spilled = 0;
        for (Partition p : parts) {
            // Serialized storage packs ~3x tighter (model it simply).
            long sz = level.serialized ? p.getDeserializedBytes() / 3 : p.getDeserializedBytes();
            sz *= level.replication; // replication multiplies storage
            if (level.useMemory && used + sz <= memoryCapacityBytes) {
                used += sz;
            } else if (level.useDisk) {
                spilled += sz;        // spill to disk instead of dropping
            } else {
                log.warning(() -> "partition " + p.getId()
                        + " dropped (memory full, no disk) → recompute from lineage later");
            }
        }
        final long u = used, s = spilled;
        log.info(() -> "stored: memoryUsed=" + u + "B, spilledToDisk=" + s
                + "B, replicas=" + level.replication);
    }
}
