package com.bank.persist;

import com.bank.persist.model.Partition;
import com.bank.persist.storage.*;
import java.util.List;
import java.util.logging.*;

public class PersistDemo {
    private static final Logger log = Logger.getLogger(PersistDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new PersistLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        Store store = new Store(100_000_000L); // 100 MB executor storage

        // Small reused dataset → plain cache (default level is fine).
        List<Partition> small = List.of(
            new Partition(0, 20_000_000), new Partition(1, 20_000_000));
        log.info("=== small dataset: cache() ===");
        store.cache(small);

        // Large dataset → persist MEMORY_AND_DISK_SER (packs tight, spills gracefully).
        List<Partition> large = List.of(
            new Partition(0, 60_000_000), new Partition(1, 60_000_000),
            new Partition(2, 60_000_000));
        log.info("=== large dataset: persist(MEMORY_AND_DISK_SER) ===");
        store.persist(large, StorageLevel.memoryAndDiskSer());

        // Critical dataset → persist with replication so a lost executor won't recompute.
        log.info("=== critical dataset: persist(MEMORY_AND_DISK_2) ===");
        store.persist(small, StorageLevel.memoryAndDisk2());
    }
}

